package com.paymentledger.ledger.payments;

/** The ISO 20022 reason code the scheme gives with a Scheme Rejection. */
public enum SchemeReasonCode {
  /** Incorrect account number. */
  AC01,
  /** Closed account number. */
  AC04,
  /** Transaction forbidden on this type of account. */
  AG01,
  /** Not specified reason, generated by the agent. */
  MS03
}
